import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int a = sc.nextInt();
        int b = sc.nextInt();
        int x = a;
        int y = b;
        System.out.println(x++);
        System.out.println(++x);
        System.out.println(y--);
        System.out.println(--y);
        System.out.println(x + y);
    }
}

import java.util.Scanner;

public class Main {
