        int b = sc.nextInt();
        int c = sc.nextInt();
        System.out.println(a + b * c);
        System.out.println((a + b) * c);
        System.out.println(a - b / c);
        System.out.println((a - b) / c);
        System.out.println(a * b % c);
        System.out.println(a + b % c);
    }
}

import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int cost = sc.nextInt();
        int friends = sc.nextInt();
        int share = cost / friends;
        int left = cost % friends;
